CREATE TABLE IF NOT EXISTS execution_workspaces(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL,milestone_id UUID NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN('DRAFT','ACTIVE','SUSPENDED','SUBMITTED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS work_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),execution_workspace_id UUID NOT NULL REFERENCES execution_workspaces(id),deliverable_id UUID NOT NULL,title TEXT NOT NULL,assignee_id UUID NOT NULL,status TEXT NOT NULL CHECK(status IN('ASSIGNED','IN_PROGRESS','SUBMITTED','CANCELLED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS progress_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),work_item_id UUID NOT NULL REFERENCES work_items(id),stage TEXT NOT NULL CHECK(stage IN('DECLARED','EVIDENCED','VALIDATED','ACCEPTED','FINANCIALLY_EARNED')),percent_complete NUMERIC NOT NULL CHECK(percent_complete BETWEEN 0 AND 100),earned_value_amount_minor BIGINT,reported_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence_requirements(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),deliverable_id UUID NOT NULL,kind TEXT NOT NULL,description TEXT NOT NULL,mandatory BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence_packages(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),work_item_id UUID NOT NULL REFERENCES work_items(id),deliverable_id UUID NOT NULL,files JSONB NOT NULL CHECK(jsonb_array_length(files)>0),chain_of_custody JSONB NOT NULL,status TEXT NOT NULL CHECK(status IN('SUBMITTED','VERIFIED','REJECTED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS validation_tests(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),work_item_id UUID NOT NULL REFERENCES work_items(id),acceptance_criterion_id UUID NOT NULL,method TEXT NOT NULL CHECK(method IN('MANUAL','AUTOMATED')),result TEXT NOT NULL CHECK(result IN('PASS','FAIL','CONDITIONAL_PASS','WAIVED')),notes TEXT NOT NULL,evidence_package_id UUID REFERENCES evidence_packages(id),retest_of UUID REFERENCES validation_tests(id),tested_by UUID NOT NULL,tested_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quality_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),execution_workspace_id UUID NOT NULL REFERENCES execution_workspaces(id),standards JSONB NOT NULL CHECK(jsonb_array_length(standards)>0),inspection_frequency TEXT NOT NULL,status TEXT NOT NULL CHECK(status='ACTIVE'),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS defects(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),work_item_id UUID NOT NULL REFERENCES work_items(id),severity TEXT NOT NULL CHECK(severity IN('MINOR','MAJOR','CRITICAL')),description TEXT NOT NULL,root_cause TEXT,status TEXT NOT NULL CHECK(status IN('OPEN','IN_REWORK','RESOLVED','CLOSED')),raised_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS quality_gate_results(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),work_item_id UUID NOT NULL REFERENCES work_items(id),passed BOOLEAN NOT NULL,open_defect_count INTEGER NOT NULL,critical_defect_count INTEGER NOT NULL,evaluated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS work_items_execution_workspace_idx ON work_items(workspace_id,execution_workspace_id);CREATE INDEX IF NOT EXISTS progress_records_work_item_idx ON progress_records(workspace_id,work_item_id);CREATE INDEX IF NOT EXISTS evidence_packages_work_item_idx ON evidence_packages(workspace_id,work_item_id);CREATE INDEX IF NOT EXISTS validation_tests_work_item_idx ON validation_tests(workspace_id,work_item_id,acceptance_criterion_id);CREATE INDEX IF NOT EXISTS defects_work_item_status_idx ON defects(workspace_id,work_item_id,status);
ALTER TABLE execution_workspaces ENABLE ROW LEVEL SECURITY;ALTER TABLE work_items ENABLE ROW LEVEL SECURITY;ALTER TABLE progress_records ENABLE ROW LEVEL SECURITY;ALTER TABLE evidence_requirements ENABLE ROW LEVEL SECURITY;ALTER TABLE evidence_packages ENABLE ROW LEVEL SECURITY;ALTER TABLE validation_tests ENABLE ROW LEVEL SECURITY;ALTER TABLE quality_plans ENABLE ROW LEVEL SECURITY;ALTER TABLE defects ENABLE ROW LEVEL SECURITY;ALTER TABLE quality_gate_results ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['execution_workspaces','work_items','progress_records','evidence_requirements','evidence_packages','validation_tests','quality_plans','defects','quality_gate_results'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['progress_records','evidence_requirements','evidence_packages','validation_tests','quality_plans','defects','quality_gate_results'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
